    def test_3_values(self):
        from src.postcodes import City
        test_cases = [("Helsinki", "00100"), 
                    ("Turku", "20100"),
                    ("Tampere", "33100"),
                    ("Rovaniemi", "96100"),
                    ("Oulu", "90100")]
        val = City.postcodes

        for test_case in test_cases:
